import Foundation

func settingsTokens(root: URL) throws -> Data {
    let source =
        try JSONSerialization.jsonObject(
            with: Data(contentsOf: root.appending(path: "Tools/TokenGen/Settings.source.json"))) as! [String: Any]
    var code =
        "// Generated by Tools/TokenGen from Settings boards and components. Do not edit.\nimport Foundation\nnonisolated public enum SettingsTokens {\n"
    for name in source.keys.sorted() {
        let metric = source[name] as! [String: String]
        let board = try String(contentsOf: root.appending(path: metric["source"]!), encoding: .utf8)
        let values = try captures(metric["pattern"]!, in: board)
        guard let raw = values.first, Double(raw) != nil, Set(values).count == 1 else {
            throw GenerationError.invalid("Settings metric changed: \(name)")
        }
        let value = name.hasSuffix("Ratio") ? String(Double(raw)! / 100) : raw
        code +=
            "public static var \(name): \(name.hasSuffix("Opacity") || name.hasSuffix("Ratio") ? "Double" : "CGFloat") { \(value) }\n"
    }
    let planBoard = try String(
        contentsOf: root.appending(path: "_design/canvas/SetPlanCredits.dc.html"), encoding: .utf8)
    let rowWidths = try captures(
        #"width: ([0-9]+)px; height: 16px; border-radius: 9999px; overflow: hidden;"><x-import"#, in: planBoard
    ).suffix(3)
    guard rowWidths.count == 3 else { throw GenerationError.invalid("Settings skeleton rows changed") }
    code += "public static var skeletonRowWidths: [CGFloat] { [\(rowWidths.joined(separator: ", "))] }\n"
    code += "}\nextension Typography {\n"
    for (name, file, pattern) in [
        ("settingsHint", "SetProfile", #"<p style="([^"]*font-size: 13px; line-height: 18px[^"]*)""#),
        ("settingsPromptBody", "PasswordPrompt", #"<p style="([^"]*font-size: 15px; line-height: 22px[^"]*)""#),
        ("settingsCodes", "Set2FAOn", #"<ul aria-label="[^"]+" style="([^"]+)""#),
        ("settingsTime", "SetBodyClock", #"<span style="(font-size: 24px;[^"]+)""#),
        ("settingsEyebrow", "SetPreferences", #"<h2 style="([^"]+)""#),
    ] {
        let board = try String(contentsOf: root.appending(path: "_design/canvas/\(file).dc.html"), encoding: .utf8)
        guard let declaration = try captures(pattern, in: board).first,
            let size = try captures(#"font-size: ([0-9.]+)px"#, in: declaration).first,
            let line = try captures(#"line-height: ([0-9.]+)px"#, in: declaration).first
        else {
            throw GenerationError.invalid("Settings typography changed: \(name)")
        }
        let weight = try captures(#"font-weight: ([0-9]+)"#, in: declaration).first ?? "400"
        let tracking =
            try captures(#"letter-spacing: ([0-9.]+)em"#, in: declaration).first.map { Double($0)! * Double(size)! }
            ?? 0
        code +=
            "public static var \(name): Style { Style(face: .figtree\(weight), size: \(size), lineHeight: \(line), tracking: \(tracking), relativeTo: .body) }\n"
    }
    for (name, base, weight) in [
        ("settingsRow", "screenBodyLg", "500"), ("settingsStrong", "screenBodyLg", "600"),
        ("settingsPill", "screenBody", "500"), ("settingsBadge", "screenMeta", "500"),
    ] {
        code +=
            "public static var \(name): Style { Style(face: .figtree\(weight), size: \(base).size, lineHeight: \(base).lineHeight, tracking: \(base).tracking, relativeTo: .body) }\n"
    }
    code += "}\n"
    return try formattedSwift(code, root: root)
}
